// YOYO cafe: deferred sharper scene images (768px cards + 1280px swaps).
// Loaded with defer after first paint; merges into ASSET_DATA and
// upgrades the card thumbnails from 480px to 768px.
(function(){var d={"assets/bar-768.webp":"data:image/webp;base64,","assets/bar.webp":"data:image/webp;base64,","assets/entrance-768.webp":"data:image/webp;base64,","assets/entrance.webp":"data:image/webp;base64,","assets/hero-768.webp":"data:image/webp;base64,","assets/interior-768.webp":"data:image/webp;base64,","assets/interior.webp":"data:image/webp;base64,","assets/seating-768.webp":"data:image/webp;base64,","assets/seating.webp":"data:image/webp;base64,","assets/streetside-768.webp":"data:image/webp;base64,","assets/streetside.webp":"data:image/webp;base64,","assets/terrace-768.webp":"data:image/webp;base64,","assets/terrace.webp":"data:image/webp;base64,","assets/window-768.webp":"data:image/webp;base64,","assets/window.webp":"data:image/webp;base64,","assets/windowseat-768.webp":"data:image/webp;base64,","assets/windowseat.webp":"data:image/webp;base64,","assets/snow-day.webp":"data:image/webp;base64,","assets/snow-day-768.webp":"data:image/webp;base64,","assets/snow-christmas.webp":"data:image/webp;base64,","assets/snow-christmas-768.webp":"data:image/webp;base64,","assets/autumn-rain.webp":"data:image/webp;base64,","assets/autumn-rain-768.webp":"data:image/webp;base64,"};if(window.ASSET_DATA){Object.assign(window.ASSET_DATA,d);}else{window.ASSET_DATA=d;}try{var imgs=document.querySelectorAll('.scene-card img');for(var i=0;i<imgs.length;i++){var img=imgs[i];var btn=img.closest?img.closest('.scene-card'):null;if(!btn) continue;var id=btn.getAttribute('data-scene-id'); if(!id) continue;var hi=window.ASSET_DATA['assets/'+id+'-768.webp'];if(hi && img.getAttribute('src')!==hi){img.src=hi;}}}catch(e){}})();
